package de.lazytv.pro.catalog;

import android.content.Context;
import java.net.URI;
import java.util.LinkedHashMap;
import java.util.Map;
import org.json.JSONObject;
import de.lazytv.pro.playlist.*;

public class CatalogEngine {
    private static final String IPTV_ORG_COUNTRY_PLAYLIST = "https://iptv-org.github.io/iptv/index.country.m3u";
    private static final Map<String, StalkerCatalogSource> STALKER_SESSIONS = new LinkedHashMap<String, StalkerCatalogSource>(8, 0.75f, true);
    private static synchronized StalkerCatalogSource stalker(Playlist p) {String key=p.getId()+"\n"+p.getUrl()+"\n"+p.getMacAddress();StalkerCatalogSource source=STALKER_SESSIONS.get(key);if(source==null){source=new StalkerNativePortalClient();STALKER_SESSIONS.put(key,source);if(STALKER_SESSIONS.size()>8)STALKER_SESSIONS.remove(STALKER_SESSIONS.keySet().iterator().next());}return source;}
    public Catalog load(Context c,Playlist p)throws CatalogException{if(p!=null&&p.getType()==PlaylistType.FREE_TV)return loadFreeTv(c,p);String e=PlaylistValidator.validateForConnect(c,p);if(e!=null)throw new CatalogException(e);switch(p.getType()){case M3U_URL:case M3U_FILE:return new M3uCatalogSource().load(c,p);case XTREAM_CODES:return new XtreamCatalogSource(c).load(p);case STALKER_PORTAL:return stalker(p).load(p);default:throw new CatalogException("Lloj burimi i panjohur");}}
    private Catalog loadFreeTv(Context c,Playlist source)throws CatalogException{Playlist publicSource=new Playlist(source==null?"builtin-free-tv":source.getId(),"FREE TV • iptv-org",PlaylistType.M3U_URL,IPTV_ORG_COUNTRY_PLAYLIST,"","","",source==null?System.currentTimeMillis():source.getUpdatedAt());return new M3uCatalogSource().load(c,publicSource);}
    public Catalog loadType(Context c,Playlist p,CatalogType t)throws CatalogException{if(p!=null&&p.getType()==PlaylistType.FREE_TV)return loadFreeTv(c,p);String e=PlaylistValidator.validateForConnect(c,p);if(e!=null)throw new CatalogException(e);String key=CatalogDiskCache.key(p.getId()+"|"+p.getUpdatedAt(),t);Catalog cached=CatalogDiskCache.get(c,key);if(cached!=null)return cached;Catalog out;if(p.getType()==PlaylistType.STALKER_PORTAL)out=stalker(p).loadType(p,t);else if(p.getType()==PlaylistType.XTREAM_CODES)out=new XtreamCatalogSource(c).loadType(p,t);else out=load(c,p);CatalogDiskCache.put(c,key,out);return out;}
    public Map<String,String> loadMovieInfo(Playlist p,StreamItem movie)throws CatalogException{if(p.getType()==PlaylistType.XTREAM_CODES)return new XtreamVodInfoSource().load(p,movie.id);if(p.getType()==PlaylistType.STALKER_PORTAL)return stalker(p).loadMovieInfo(p,movie);return movie.metadata;}
    public SeriesDetails loadSeries(Playlist p,Series s)throws CatalogException{if(s instanceof M3uSeries)return((M3uSeries)s).details();if(p.getType()==PlaylistType.XTREAM_CODES)return new XtreamCatalogSource().loadSeries(p,s.id);if(p.getType()==PlaylistType.STALKER_PORTAL)return stalker(p).loadSeries(p,s);throw new CatalogException("Ky burim nuk ekspozon seasons/episodes të strukturuara");}
    public ResolvedStream resolveLiveStream(Playlist playlist,StreamItem item)throws CatalogException{return new StreamResolver(playlist.getType()==PlaylistType.STALKER_PORTAL?stalker(playlist):null,null,false).resolve(playlist,item);}
    public EpgSchedule loadLiveSchedule(Playlist playlist,StreamItem item)throws CatalogException{if(playlist==null||item==null)return EpgSchedule.empty();String body;if(playlist.getType()==PlaylistType.STALKER_PORTAL){StalkerCatalogSource source=stalker(playlist);if(!(source instanceof StalkerNativePortalClient))return EpgSchedule.empty();body=((StalkerNativePortalClient)source).loadEpg(playlist,item.id);}else if(playlist.getType()==PlaylistType.XTREAM_CODES&&!(item instanceof M3uStreamItem)){body=xtreamScheduleGet(playlist,"get_short_epg",item.id);try{EpgSchedule compact=EpgSchedule.parse(body,item.id,System.currentTimeMillis());if(compact.current!=null||compact.next!=null)return compact;}catch(CatalogException ignored){}body=xtreamScheduleGet(playlist,"get_simple_data_table",item.id);}else return EpgSchedule.empty();return EpgSchedule.parse(body,item.id,System.currentTimeMillis());}
    private String xtreamScheduleGet(Playlist p,String action,String streamId)throws CatalogException{String url=XtreamUrlBuilder.api(p,action,"stream_id",streamId);try{return HttpClient.get(url,null);}catch(CatalogException first){String m=first.getMessage()==null?"":first.getMessage();boolean network=m.contains("ConnectException")||m.contains("TLS/SSL")||m.contains("brenda afatit");if(!network)throw first;String alt;if(url.regionMatches(true,0,"https://",0,8))alt="http://"+url.substring(8);else if(url.regionMatches(true,0,"http://",0,7))alt="https://"+url.substring(7);else throw first;try{return HttpClient.get(alt,null);}catch(CatalogException ignored){throw first;}}}
    public ResolvedStream resolveStream(Playlist p,StreamItem i)throws CatalogException{ResolvedStream r=new StreamResolver(p!=null&&p.getType()==PlaylistType.STALKER_PORTAL?stalker(p):null).resolve(p,i);return enrichXtreamSelection(p,i,r);}
    public ResolvedStream resolveStream(Context c,Playlist p,StreamItem i)throws CatalogException{ResolvedStream r=new StreamResolver(p!=null&&p.getType()==PlaylistType.STALKER_PORTAL?stalker(p):null,c).resolve(p,i);return enrichXtreamSelection(p,i,r);}
    private ResolvedStream enrichXtreamSelection(Playlist p,StreamItem i,ResolvedStream r){if(p==null||i==null||r==null||p.getType()!=PlaylistType.XTREAM_CODES)return r;if(i instanceof M3uStreamItem)return r;if(i.type==CatalogType.LIVE)return enrichXtreamLiveEpg(p,i,r);return r;}
    private ResolvedStream enrichXtreamLiveEpg(Playlist p,StreamItem i,ResolvedStream r){try{Map<String,String> epg=new XtreamCatalogSource().loadLiveEpg(p,i.id);if(epg==null||epg.isEmpty())return r;Map<String,String> metadata=new LinkedHashMap<>(r.metadata);metadata.putAll(epg);return new ResolvedStream(r.url,r.streamType,r.title,r.artwork,r.epgId,r.headers,metadata);}catch(Exception ignored){return r;}}
    public ResolvedStream refreshStream(Playlist p,StreamItem i)throws CatalogException{return resolveStream(p,i);}
    public void close(){}
}
